// Tests/RoadieAXTests/ReactiveTilingAXTests.swift (même fichier : accès aux types privés SpyAXFrameIO, index, window)
@Suite
@MainActor
struct ProductionDefaultsWiringTests {
    @Test
    func defaultObserverAbsorbsEchoRecordedInSharedRegistry() {
        let windowID: UInt32 = 0xD00D_0001   // unique : le registre partagé est global au processus
        let frame = CGRect(x: 0, y: 0, width: 800, height: 600)
        let now = Date()
        WrittenFrameRegistry.shared.record(windowID: windowID, requested: frame, readBack: frame, generation: 1, at: now)
        defer { WrittenFrameRegistry.shared.forget(windowID: windowID) }
        var received: [AXWindowEvent] = []
        let observer = AXWindowEventObserver(onEvent: { received.append($0) })   // init de main.swift
        observer.dispatch(
            AXWindowEvent(name: kAXWindowMovedNotification as String, pid: 3, windowID: windowID),
            observedFrame: frame.offsetBy(dx: 1, dy: 0), now: now.addingTimeInterval(0.05)
        )
        #expect(received.isEmpty)
    }

    @Test
    func defaultWriterRecordsInSharedRegistryWithSharedGeneration() {
        let windowID: UInt32 = 0xD00D_0002
        let io = SpyAXFrameIO()
        io.windows[7_002] = index(pid: 7_002, ids: [windowID])
        let target = CGRect(x: 0, y: 0, width: 300, height: 200)
        io.readBack = target
        defer { WrittenFrameRegistry.shared.forget(windowID: windowID) }
        let writer: any WindowFrameWriting = AXWindowFrameWriter(io: io)   // registre, index et génération par défaut
        let generation = PlacementGeneration.shared.next()

        _ = writer.setFrame(target, of: window(windowID, pid: 7_002), generation: generation)

        #expect(WrittenFrameRegistry.shared.entry(for: windowID)?.generation == generation)
    }
}

