// Sources/RoadieDaemon/TickScheduler.swift
extension TickScheduler.Coalescing {
    /// Déplacement ou redimensionnement : changement externe (30 ms). Autre notification : événement (15 ms).
    public static func forAXNotification(_ name: String) -> TickScheduler.Coalescing {
        name == kAXWindowMovedNotification as String || name == kAXWindowResizedNotification as String
            ? .externalChange : .event
    }
}
