func advance(by seconds: TimeInterval) {
    let target = clock.now.addingTimeInterval(seconds)
    while let next = items.filter({ $0.due <= target }).min(by: { $0.due < $1.due }) {
        items.removeAll { $0.id == next.id }
        clock.now = max(clock.now, next.due)
        next.action()
    }
    clock.now = target
}

findings.remediation_code:
func advance(by seconds: TimeInterval, maxFires: Int = 1_000) {
    let target = clock.now.addingTimeInterval(seconds)
    var fires = 0
    while let next = items.filter({ $0.due <= target }).min(by: { $0.due < $1.due }) {
        fires += 1
        guard fires <= maxFires else {
            Issue.record("minuterie emballée : plus de \(maxFires) exécutions avant \(target)")
            break
        }
        items.removeAll { $0.id == next.id }
        clock.now = max(clock.now, next.due)
        next.action()
    }
    clock.now = target
}
